import{_ as s,C as n,o,c as i,a5 as a,E as r}from"./chunks/framework.BPFk9-tb.js";const g=JSON.parse('{"title":"从 FunASR 到 Confucius4-R2T2","description":"","frontmatter":{"date":"2026-10-04T14:21:40","title":"从 FunASR 到 Confucius4-R2T2","categories":["AI","FunASR","Confucius4-R2T2"],"tags":["AI","FunASR","Confucius4-R2T2"]},"headers":[{"level":2,"title":"一、为什么选 Confucius4-R2T2","slug":"一、为什么选-confucius4-r2t2","link":"#一、为什么选-confucius4-r2t2","children":[]},{"level":2,"title":"二、技术验证","slug":"二、技术验证","link":"#二、技术验证","children":[]},{"level":2,"title":"三、FunASR 降级为预处理层","slug":"三、funasr-降级为预处理层","link":"#三、funasr-降级为预处理层","children":[]},{"level":2,"title":"四、量化怎么选：Q8_0 是甜点位","slug":"四、量化怎么选-q8-0-是甜点位","link":"#四、量化怎么选-q8-0-是甜点位","children":[]},{"level":2,"title":"五、同题 A/B：可以换成 R2T2","slug":"五、同题-a-b-可以换成-r2t2","link":"#五、同题-a-b-可以换成-r2t2","children":[]},{"level":2,"title":"六、最终形态：一个容器一个端口","slug":"六、最终形态-一个容器一个端口","link":"#六、最终形态-一个容器一个端口","children":[]},{"level":2,"title":"七、代价清单","slug":"七、代价清单","link":"#七、代价清单","children":[]},{"level":2,"title":"八、写在最后","slug":"八、写在最后","link":"#八、写在最后","children":[]}],"relativePath":"posts/course100/066.md","filePath":"posts/course100/066.md"}'),l={name:"posts/course100/066.md"};function d(p,t,u,c,h,E){const e=n("MermaidBlock");return o(),i("div",null,[t[0]||(t[0]=a('<blockquote><p>七个多月前，我写过一篇《部署和使用 FunASR》，记录从 whisper 换到 FunASR 的过程。七个多月后，我把这套服务换成了 Confucius4-R2T2。这篇文章完整记录决策链：为什么换、架构怎么定、量化怎么选、靠什么数据下结论，以及付出了什么代价。</p></blockquote><h2 id="一、为什么选-confucius4-r2t2" tabindex="-1">一、为什么选 Confucius4-R2T2 <a class="header-anchor" href="#一、为什么选-confucius4-r2t2" aria-label="Permalink to &quot;一、为什么选 Confucius4-R2T2&quot;">​</a></h2><p>我有个 Java 小项目：采集音视频，本地转写，入库供检索。环境使用 MacBook Pro M1 Pro (32GB) + OrbStack，无 GPU。</p><p>这套转写栈已经做了两次迭代。一开始使用 whisper：识别不准、没有标点、时不时蹦出繁体，最难受的是会在结尾冒出些奇怪的内容 —— 长期靠 LLM 修正表兜底。后来 FunASR(aliyun funasr runtime: Paraformer-large + VAD + 标点 + ngram 语言模型 + 数字规整)就是为了治这些毛病换的：检测、识别、标点、数字规整一站式，服务端自带 ffmpeg，还支持热词；WebSocket 协议，单容器，RTF≈0.05(Real-Time Factor，实时率 = 转写耗时 ÷ 音频时长，小于 1 即比实时快，越小越快) —— 3.7 分钟的音频 11 秒转完。一用就是七个多月，看起来够用了。</p><p>最近看到 Confucius4-R2T2 霸榜的消息，网易有道子曰-Live 系列的 <strong>Confucius4-R2T2</strong>：与 Qwen3-ASR 同架构的 2B 微调版。同期开源的还有流式翻译模型 Confucius4-T3PO，两个模型发布时在 HuggingFace 双双登顶各自细分 Trending 榜 —— R2T2 是 ASR 榜第一。</p><p>让我觉得可以再次迭代的原因，我的 Mac 能跑得起来。官方放出了 GGUF 量化仓库(<a href="https://huggingface.co/netease-youdao/Confucius4-R2T2-GGUF" target="_blank" rel="noreferrer">netease-youdao/Confucius4-R2T2-GGUF</a> )，海外开发者还主动做了 C++ 移植(audio.cpp)；llama.cpp 官方二进制直接能跑，Ollama 一条命令就能拉起。别人愿意真花时间做适配，说明这东西能用。</p><p>之前有人问我 FunASR 对比 Qwen3-ASR 怎么样 —— 严格说 FunASR 是一套框架/平台，包含一整套流水线，其中负责转写的默认模型是 Fun-Asr，是可以更换的（比如换成 Paraformer、SenseVoice，Qwen3-ASR 也可以），具体参考 HuggingFace 上的这篇讨论 <a href="https://huggingface.co/Qwen/Qwen3-ASR-1.7B/discussions/24" target="_blank" rel="noreferrer">https://huggingface.co/Qwen/Qwen3-ASR-1.7B/discussions/24</a> 。这次同题对比也算顺带验证了那个问题，毕竟 Confucius4-R2T2 就是基于 Qwen3-ASR 架构。</p><h2 id="二、技术验证" tabindex="-1">二、技术验证 <a class="header-anchor" href="#二、技术验证" aria-label="Permalink to &quot;二、技术验证&quot;">​</a></h2><p>新栈全部实测基于 llama.cpp b11146、funasr 1.4.16、GGUF Q8_0(1.71GiB)；旧栈为 aliyun funasr-runtime-sdk-cpu-0.4.7。</p><p>让 AI 作了技术验证，得出五条结论：</p><ol><li><strong>用 FunASR 直接跑 Confucius4-R2T2 大模型，CPU 上 RTF≈90</strong>，完全不可用(3.7 分钟音频要转 4~6 小时)；但它的两个小模型是<strong>毫秒级</strong>的 —— VAD(fsmn-vad)RTF 0.003，说话人嵌入(cam++)RTF 0.006。</li><li>**llama.cpp 只有 HTTP(含 SSE)，没有 WebSocket。**旧栈的 WS 客户端要自己初始化配置、按块发送音频、发结束标志、解析回包，其实也不简单；新栈换成一次 HTTP multipart 上传就完事，倒也省事。</li><li><strong>mp3 可以直传 llama.cpp、mp4/AAC 不行</strong>，报 &quot;Failed to tokenize prompt&quot;。视频必须先经 ffmpeg 抽音轨。</li><li><strong>单请求受上下文限制</strong>：音频约占 13 token/s，<code>-c 4096</code> 下约 5.2 分钟封顶。长音频必须分段。</li><li>输出带 <code>language Chinese&amp;lt;asr_text&amp;gt;</code> 前缀，需要剥离。</li></ol><p>FunASR 不能直接使用，Mac 跑不动，特别是在容器里跑，应该以 llama.cpp 为主，但是因为 FunASR 的 VAD 和说话人嵌入等还是不错的，也应该吸收过来。</p><h2 id="三、funasr-降级为预处理层" tabindex="-1">三、FunASR 降级为预处理层 <a class="header-anchor" href="#三、funasr-降级为预处理层" aria-label="Permalink to &quot;三、FunASR 降级为预处理层&quot;">​</a></h2><p>最终架构各取所长：</p>',14)),r(e,{code:"flowchart%20TD%0A%20%20%20%20A(%5B%22%E9%9F%B3%E9%A2%91%2F%E8%A7%86%E9%A2%91%22%5D)%20--%3E%20B%5B%22ffmpeg%20%E8%BD%AC%2016k%20%E5%8D%95%E5%A3%B0%E9%81%93%22%5D%0A%20%20%20%20subgraph%20PRE%5B%22%E6%AF%AB%E7%A7%92%E7%BA%A7%E5%B0%8F%E6%A8%A1%E5%9E%8B%2C%20CPU%20%E9%9A%8F%E4%BE%BF%E8%B7%91%22%5D%0A%20%20%20%20%20%20%20%20P1%5B%22fsmn-vad%20%E6%8C%89%E9%9D%99%E9%9F%B3%E5%88%87%E6%AE%B5%22%5D%0A%20%20%20%20%20%20%20%20P2%5B%22cam%2B%2B%20%E8%AF%B4%E8%AF%9D%E4%BA%BA%E5%B5%8C%E5%85%A5%20%2B%20%E5%B1%82%E6%AC%A1%E8%81%9A%E7%B1%BB%3Cbr%2F%3E(%E5%B0%8F%E4%BA%8E%202s%20%E7%A2%8E%E6%AE%B5%E5%B0%B1%E8%BF%91%E7%BB%A7%E6%89%BF%E9%82%BB%E6%AE%B5%E6%A0%87%E7%AD%BE)%22%5D%0A%20%20%20%20%20%20%20%20P3%5B%22%E7%9B%B8%E9%82%BB%E5%90%8C%E8%AF%B4%E8%AF%9D%E4%BA%BA%E6%AE%B5%E5%90%88%E5%B9%B6%E4%B8%BA%20%E2%89%A455s%20%E8%BD%AC%E5%86%99%E5%9D%97%22%5D%0A%20%20%20%20%20%20%20%20P1%20--%3E%20P2%20--%3E%20P3%0A%20%20%20%20end%0A%20%20%20%20B%20--%3E%20P1%0A%20%20%20%20P3%20--%3E%20T%5B%22llama.cpp%20GGUF(Q8_0)%20%E9%80%90%E5%9D%97%E8%BD%AC%E5%86%99%3Cbr%2F%3E%E9%87%8D%E6%B4%BB%E4%BA%A4%E7%BB%99%E9%87%8F%E5%8C%96%E5%90%8E%E7%9A%84%E5%A4%A7%E6%A8%A1%E5%9E%8B%22%5D%0A%20%20%20%20T%20--%3E%20O(%5B%22%E8%BE%93%E5%87%BA%3A%20JSON%20%E8%AF%B4%E8%AF%9D%E4%BA%BA%E8%BD%AE%E6%AC%A1%20%2B%20Markdown%20%E6%96%87%E7%A8%BF%22%5D)"}),t[1]||(t[1]=a('<p>FunASR 从“转写引擎”降级成“预处理层”，只负责 VAD 切段和说话人分离；文本生成的重活全部交给 GGUF，比 FunASR 调用 Confucius4-R2T2 原生 CPU 转写快两个数量级。</p><p>说话人分离的输出长这样：</p><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-light-font-weight:bold;--shiki-dark:#E1E4E8;--shiki-dark-font-weight:bold;">**【说话人 1】**</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(00:00-00:06)之前有顾客自己带酒水,也没加收钱或者不让喝。</span></span></code></pre></div><p>实测：224.5 秒独白音频，<code>speakers=1</code> 无误检；42.3 秒双人交替对话，<code>speakers=2</code> 且四轮完美交替。预处理开销可以忽略 —— 耗时全在转写本身。</p><h2 id="四、量化怎么选-q8-0-是甜点位" tabindex="-1">四、量化怎么选：Q8_0 是甜点位 <a class="header-anchor" href="#四、量化怎么选-q8-0-是甜点位" aria-label="Permalink to &quot;四、量化怎么选：Q8_0 是甜点位&quot;">​</a></h2><p>GGUF 部署要选量化档。7 个测试文件(约 7.5 分钟)做全量化 A/B：</p><table tabindex="0"><thead><tr><th>量化</th><th>容器 CPU RTF</th><th>镜像体积</th><th>质量</th></tr></thead><tbody><tr><td>f16</td><td>0.52-0.57</td><td>6.87GB</td><td>基准</td></tr><tr><td><strong>Q8_0</strong></td><td><strong>0.42-0.45</strong></td><td><strong>5.26GB</strong></td><td><strong>与 f16 字词级几乎全同</strong></td></tr><tr><td>Q4_K_M</td><td>0.42</td><td>4.24GB</td><td>歧义短语上与 f16 各有输赢</td></tr></tbody></table><p>一个有意思的发现：f16 在容器 CPU 和 Mac Metal 上输出<strong>逐字节一致</strong> —— 意味着结果可复现，所有 A/B 对比因此可信。</p><p>结论：Q8_0 质量≈f16、速度≈Q4_K_M，标准的甜点位，设为默认模型。差异仅在个别标点与语气词(Q8 的标点反而更规范)；至于“推倒重来/推导出来”这类音频本身就歧义的短语，任何引擎、任何量化都会翻转，不计分。</p><h2 id="五、同题-a-b-可以换成-r2t2" tabindex="-1">五、同题 A/B：可以换成 R2T2 <a class="header-anchor" href="#五、同题-a-b-可以换成-r2t2" aria-label="Permalink to &quot;五、同题 A/B：可以换成 R2T2&quot;">​</a></h2><p>用 5 个真实 mp3(共 3.7 分钟)同题对比：</p><table tabindex="0"><thead><tr><th>维度</th><th>FunASR(aliyun runtime)</th><th>R2T2(Q8_0)</th></tr></thead><tbody><tr><td>幻觉</td><td>1 处：结尾凭空多出&quot;没有有没有。&quot;</td><td>无，5/5 干净收尾</td></tr><tr><td>断句</td><td>&quot;推导出来了。若干次&quot;(错位)</td><td>&quot;推倒重来了若干次&quot;(断句正确)</td></tr><tr><td>伪影</td><td>ITN 空格伪影(&quot;14 个&quot;)</td><td>无</td></tr><tr><td>语气词</td><td>丢(&quot;呃&quot;)</td><td>完整保留</td></tr><tr><td>标点</td><td>粗糙生硬</td><td>细腻自然</td></tr><tr><td>专有名词</td><td>&quot;李笑来&quot;✓ &quot;定投&quot;✓</td><td>同样 ✓</td></tr><tr><td><strong>速度</strong></td><td><strong>单文件 1.7-3.1s(RTF≈0.05)</strong></td><td>单文件 12-25s(RTF 0.42-0.45)</td></tr></tbody></table><p>质量上新栈全面占优，且没有一处实质字词错误输给对方；速度上 FunASR 快约 10 倍 —— 但我的场景是<strong>批量离线转写</strong>，RTF 0.05 和 0.42 都远快于实时，都是后台任务，没有本质区别。质量优先，决定切换成 R2T2。</p><h2 id="六、最终形态-一个容器一个端口" tabindex="-1">六、最终形态：一个容器一个端口 <a class="header-anchor" href="#六、最终形态-一个容器一个端口" aria-label="Permalink to &quot;六、最终形态：一个容器一个端口&quot;">​</a></h2><p>最后一步，把所有能力收进一个自包含镜像 <code>r2t2-gguf:latest</code>(5.26GB，模型全部内置)：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --name</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> r2t2-asr</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 8080:8080</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> r2t2-gguf:latest</span></span></code></pre></div><p>起来就是一个 ASR 网关，四组端点：</p><ul><li><code>POST /v1/audio/transcriptions</code> —— OpenAI 兼容，短音频字节级透传，老客户端零改动;</li><li><code>POST /asr/jobs</code> —— 提交长音视频任务(mp4/ts/m4a 等任意 ffmpeg 支持的格式)，返回 202 + job_id;</li><li><code>GET /asr/jobs/{id}</code> —— 轮询进度，逐块更新 n/N;</li><li><code>DELETE /asr/jobs/{id}</code> —— 取消，块间生效，保留已完成部分。</li></ul><p>内部逻辑：≤270s 的音频单发直译；超了就自动走完整管线 —— ffmpeg 抽轨、VAD、说话人分离、分块转写。网关本体 <code>asr_server.py</code> 约 300 行，纯 Python 标准库，没有给镜像增加任何依赖。Java 侧只对接两个方法：短音频同步透传；长视频提交任务 + 10 秒轮询 + 进度停滞看门狗，结果按“源文件.txt”旁路缓存，幂等可重试。</p><p>**为什么长音频必须分块，不能放大上下文硬扛？**实测过:<code>-c 32768</code> 单发 10.4 分钟尚可用(RTF 0.72)；但 31.2 分钟时生成速度从 6.6 token/s 一路衰减到 3.0 以下，<strong>比实时还慢</strong>(RTF&gt;2)。而分块方案的 RTF 恒定在 0.43-0.50，与时长无关 —— 31.2 分钟音频分块转写 835.8s(RTF 0.447)。</p><p><strong>实战验证</strong>：63.1 分钟的真实 mp4(AV1+AAC，英文演讲)直接扔给网关 —— 容器内自动抽轨，74 块、识别出 3 个说话人、45,367 字符、端到端 1751.6s，<strong>RTF 0.462</strong>，与预估一致；首尾干净，无幻觉；中途 DELETE 也能干净取消。以我现在 Mac 上的容器跑法，29 分钟能转完一小时视频。</p><p>顺带记录一个值得警惕的 bug：早期 Dockerfile 里多源 <code>COPY fsmn-vad campplus /models/funasr/</code> 会把两个目录的<strong>内容摊平</strong>进同一层，子目录从未真正存在；而 FunASR 收到不存在的本地路径时会<strong>静默回退到在线下载</strong> —— 所谓&quot;运行时免下载&quot;其实从未成立，小模型一直是运行时在线拉的，只是恰好没人断网发现过。修复后加了显式路径检查才算闭环。</p><h2 id="七、代价清单" tabindex="-1">七、代价清单 <a class="header-anchor" href="#七、代价清单" aria-label="Permalink to &quot;七、代价清单&quot;">​</a></h2><p>切换后的问题：</p><ul><li><strong>速度慢了约 10 倍</strong>：RTF 0.42 对 0.05，一小时视频转 29 分钟。离线批量无感，但要实时出稿的场景，这套 CPU 方案不适合；</li><li><strong>热词降级</strong>：旧栈原生热词，新栈只能经 prompt 字段透传，效果依赖 llama.cpp 版本对该模型上下文偏置的支持；</li><li><strong>没有流式</strong>：需要的话得上 R2T2 官方 NVIDIA CUDA 栈；</li><li><strong>真要快还有后手</strong>：Mac 上原生 llama.cpp + Metal 能到 RTF≈0.06(容器里没有 GPU 加速)；Linux 服务器换 CUDA 版 llama.cpp 即可，镜像构建留了变体参数。</li></ul><p>换来的是：转写质量提升；说话人分离、视频直转能力上线；为 whisper 幻觉长期兜底的 LLM 修正表等防御性逻辑，这次可以正式退休了。</p><h2 id="八、写在最后" tabindex="-1">八、写在最后 <a class="header-anchor" href="#八、写在最后" aria-label="Permalink to &quot;八、写在最后&quot;">​</a></h2><p>回顾这次的迭代升级，有三点心得值得留下来：</p><ol><li>选型时与其盯着 benchmark，不如看有没有人真金白银地为它做移植、做量化、做集成。这样可以在不同的环境中验证是否适合自己。</li><li>FunASR 调用R2T2大模型在 CPU 上不可用，但它的毫秒级小模型正好补位。“新模型干重活、旧栈降级当预处理”的混合流水线，可以推广到很多&quot;大模型本地跑不动&quot;的场景。</li><li>多作 A/B 测试，要同题、要真实数据、要可复现，f16 跨设备逐字节一致，让所有对比有了基准；5 个真实 mp3 的胜负表，升级迭代决定一目了然。</li></ol>',29))])}const B=s(l,[["render",d]]);export{g as __pageData,B as default};
